Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:photos.s3.us-east-1.amazonaws.com"'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', '--allow-uploads', 's3://127.0.0.1:8080/', 'https://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --cacert server.pem --connect-to ::127.0.0.1:8080 -u AKIAIOSFODNN7EXAMPLE:s3cret -T note.txt s3://photos/note.txt s3://photos/note.txt } finally { Stop-Process $server0 }
